from __future__ import annotations

from enum import StrEnum
from typing import Any, Literal, Protocol

from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator

from foreman.hooks import (
    HookAction,
    HookError,
    HookEvent,
    HookEventKind,
    HookOutcome,
)


class HookAdapter(Protocol):
    """Translate one coding assistant's hook protocol at Foreman's boundary."""

    client: str

    def parse(self, payload: dict[str, Any]) -> HookEvent: ...

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]: ...


class CodexHookEventName(StrEnum):
    SESSION_START = "SessionStart"
    USER_PROMPT_SUBMIT = "UserPromptSubmit"
    PRE_TOOL_USE = "PreToolUse"
    POST_TOOL_USE = "PostToolUse"
    STOP = "Stop"
    SESSION_END = "SessionEnd"


class CodexHookInput(BaseModel):
    """The stable subset of Codex lifecycle input consumed by its adapter."""

    model_config = ConfigDict(extra="allow")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    hook_event_name: CodexHookEventName
    turn_id: str | None = None
    prompt: str | None = None
    tool_name: str | None = None
    tool_use_id: str | None = None
    tool_input: Any = None
    tool_response: Any = None
    stop_hook_active: bool = False
    last_assistant_message: str | None = None

    @model_validator(mode="after")
    def required_event_fields(self) -> CodexHookInput:
        if self.hook_event_name is CodexHookEventName.USER_PROMPT_SUBMIT and not (
            self.prompt and self.prompt.strip()
        ):
            raise ValueError("UserPromptSubmit requires a non-empty prompt")
        if self.hook_event_name in {
            CodexHookEventName.PRE_TOOL_USE,
            CodexHookEventName.POST_TOOL_USE,
        } and not self.tool_name:
            raise ValueError(f"{self.hook_event_name.value} requires tool_name")
        return self


_CODEX_EVENT_KINDS = {
    CodexHookEventName.SESSION_START: HookEventKind.SESSION_STARTED,
    CodexHookEventName.USER_PROMPT_SUBMIT: HookEventKind.WORK_SUBMITTED,
    CodexHookEventName.PRE_TOOL_USE: HookEventKind.BEFORE_TOOL,
    CodexHookEventName.POST_TOOL_USE: HookEventKind.AFTER_TOOL,
    CodexHookEventName.STOP: HookEventKind.WORKER_STOPPING,
    CodexHookEventName.SESSION_END: HookEventKind.SESSION_ENDED,
}


class CodexHookAdapter:
    client = "codex"

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = CodexHookInput.model_validate(payload)
        except ValidationError as error:
            raise HookError(f"invalid Codex hook input: {error}") from error
        return HookEvent(
            client=self.client,
            session_id=source.session_id,
            cwd=source.cwd,
            kind=_CODEX_EVENT_KINDS[source.hook_event_name],
            source_event_name=source.hook_event_name.value,
            turn_id=source.turn_id,
            prompt=source.prompt,
            tool_name=source.tool_name,
            tool_use_id=source.tool_use_id,
            tool_input=source.tool_input,
            tool_response=source.tool_response,
            continuation_active=source.stop_hook_active,
            last_assistant_message=source.last_assistant_message,
        )

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]:
        reason = outcome.reason or "Foreman blocked this operation"
        if outcome.action is HookAction.ALLOW:
            return {}
        if outcome.action is HookAction.INJECT_CONTEXT:
            return {
                "hookSpecificOutput": {
                    "hookEventName": event.source_event_name,
                    "additionalContext": reason,
                }
            }
        if outcome.action is HookAction.BLOCK:
            if event.kind is HookEventKind.BEFORE_TOOL:
                return {
                    "hookSpecificOutput": {
                        "hookEventName": event.source_event_name,
                        "permissionDecision": "deny",
                        "permissionDecisionReason": reason,
                    }
                }
            return {"decision": "block", "reason": reason}
        return {
            "continue": False,
            "stopReason": reason,
            "systemMessage": outcome.system_message or reason,
        }


class DeepAgentsHookInput(BaseModel):
    """Published dcode Hooks v2 wire subset, including failed tool calls."""

    model_config = ConfigDict(extra="allow")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    hook_event_name: Literal[
        "SessionStart", "UserPromptSubmit", "PreToolUse", "PostToolUse",
        "PostToolUseFailure", "Stop", "SessionEnd",
    ]
    prompt_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    prompt: str | None = None
    tool_name: str | None = None
    tool_use_id: str | None = None
    tool_input: Any = None
    tool_response: Any = None
    stop_hook_active: bool = False
    last_assistant_message: str | None = None
    error: str | None = None
    is_interrupt: bool | None = None

    @model_validator(mode="after")
    def required_deepagents_fields(self) -> DeepAgentsHookInput:
        if self.hook_event_name == "UserPromptSubmit" and not (
            self.prompt and self.prompt.strip()
        ):
            raise ValueError("UserPromptSubmit requires a non-empty prompt")
        if self.hook_event_name in {"PreToolUse", "PostToolUse", "PostToolUseFailure"}:
            if not self.tool_name or not self.tool_use_id:
                raise ValueError("tool events require tool_name and tool_use_id")
        if self.hook_event_name == "PostToolUseFailure" and self.error is None:
            raise ValueError("PostToolUseFailure requires error")
        return self


class DeepAgentsHookAdapter(CodexHookAdapter):
    # dcode accepts the same decision/context output vocabulary as Codex.
    # Post-tool stop directives are feedback in dcode; Stop and prompt hooks
    # provide the actionable turn boundary (see the integration guide).
    client = "deepagents"

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = DeepAgentsHookInput.model_validate(payload)
            kind = (
                HookEventKind.AFTER_TOOL
                if source.hook_event_name == "PostToolUseFailure"
                else _CODEX_EVENT_KINDS[source.hook_event_name]
            )
            response = source.tool_response
            if source.hook_event_name == "PostToolUseFailure":
                response = {"isError": True, "error": source.error}
                if source.is_interrupt is not None:
                    response["is_interrupt"] = source.is_interrupt
            return HookEvent(
                client=self.client,
                session_id=source.session_id,
                cwd=source.cwd,
                kind=kind,
                source_event_name=source.hook_event_name,
                work_id=source.prompt_id,
                turn_id=source.prompt_id,
                prompt=source.prompt,
                tool_name=source.tool_name,
                tool_use_id=source.tool_use_id,
                tool_input=source.tool_input,
                tool_response=response,
                continuation_active=source.stop_hook_active,
                last_assistant_message=source.last_assistant_message,
            )
        except (ValidationError, ValueError) as error:
            raise HookError(f"invalid Deep Agents hook input: {error}") from error


class PiHookInput(BaseModel):
    """Bridge envelope around Pi's native events; identities come from its host."""

    model_config = ConfigDict(extra="forbid")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    event: dict[str, Any]
    work_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    event_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    continuation_active: bool = False


_PI_EVENT_KINDS = {
    "session_start": HookEventKind.SESSION_STARTED,
    "input": HookEventKind.WORK_SUBMITTED,
    "tool_call": HookEventKind.BEFORE_TOOL,
    "tool_result": HookEventKind.AFTER_TOOL,
    "agent_before_settle": HookEventKind.WORKER_STOPPING,
    "session_shutdown": HookEventKind.SESSION_ENDED,
}
_DURABLE_EVENT_KINDS = {
    "beforeRequest": HookEventKind.WORK_SUBMITTED,
    "beforeTool": HookEventKind.BEFORE_TOOL,
    "afterTool": HookEventKind.AFTER_TOOL,
    "onYield": HookEventKind.WORKER_STOPPING,
}


class PiHookAdapter:
    client = "pi"
    event_kinds = _PI_EVENT_KINDS

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = PiHookInput.model_validate(payload)
            native = source.event
            name = native.get("type")
            if name not in self.event_kinds:
                raise ValueError(f"unsupported event {name!r}")
            durable = self.client == "pi-durable"
            call = native.get("call", {}) if durable else native
            if not isinstance(call, dict):
                raise ValueError("call must be an object")
            return HookEvent(
                client=self.client,
                session_id=source.session_id,
                cwd=source.cwd,
                kind=self.event_kinds[name],
                source_event_name=name,
                work_id=source.work_id,
                event_id=source.event_id,
                turn_id=source.work_id,
                prompt=native.get("prompt" if durable else "text"),
                tool_name=call.get("name" if durable else "toolName"),
                tool_use_id=call.get("id" if durable else "toolCallId"),
                tool_input=call.get("arguments" if durable else "input"),
                tool_response=native.get("result") if durable else (
                    {key: native[key]
                     for key in ("content", "details", "structuredContent", "isError")
                     if key in native} if name == "tool_result" else None
                ),
                continuation_active=source.continuation_active,
                last_assistant_message=native.get("last_assistant_message"),
            )
        except (ValidationError, ValueError, TypeError) as error:
            raise HookError(f"invalid {self.client} hook input: {error}") from error

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]:
        # The TypeScript bridges apply these effects through native APIs. A HALT
        # remains distinct from BLOCK (which requests a completion continuation).
        if outcome.action is HookAction.ALLOW:
            return {}
        return outcome.model_dump(mode="json", exclude_none=True)


class PiDurableHookAdapter(PiHookAdapter):
    client = "pi-durable"
    event_kinds = _DURABLE_EVENT_KINDS


_ADAPTERS: dict[str, HookAdapter] = {
    CodexHookAdapter.client: CodexHookAdapter(),
    DeepAgentsHookAdapter.client: DeepAgentsHookAdapter(),
    PiHookAdapter.client: PiHookAdapter(),
    PiDurableHookAdapter.client: PiDurableHookAdapter(),
}


def hook_adapter(client: str) -> HookAdapter:
    normalized = client.strip().lower()
    try:
        return _ADAPTERS[normalized]
    except KeyError:
        available = ", ".join(sorted(_ADAPTERS))
        raise HookError(
            f"unsupported hook client {client!r}; available clients: {available}"
        ) from None


def available_hook_clients() -> tuple[str, ...]:
    return tuple(sorted(_ADAPTERS))

from __future__ import annotations

import asyncio
import json
import re
from collections.abc import Mapping
from dataclasses import dataclass, field, replace
from datetime import UTC, datetime
from enum import StrEnum
from math import isfinite
from typing import Annotated, Any, Protocol

from pydantic import BaseModel, ConfigDict, Field, JsonValue, model_validator

from foreman.decision_models.base import DecisionModelAdapter
from foreman.decision_models.jev import JevDecisionAdapter, parse_jev_values
from foreman.request_budget import DecisionRequestBudget, RequestBudgetError
from foreman.responsibilities import ResponsibilityRegistry, ResponsibilityRoute
from foreman.usage import DecisionUsageRecorder

_ROUTE_GROUP_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*")


class ResponsibilityRoutingError(RuntimeError):
    """Incoming work could not be routed to responsibilities."""


class RouteSelection(StrEnum):
    ALL_MATCHES = "all_matches"
    BEST_MATCH = "best_match"


@dataclass(frozen=True, slots=True)
class RouteGroup:
    """A conditional routing group containing responsibilities and nested groups."""

    id: str
    route: ResponsibilityRoute
    responsibility_ids: tuple[str, ...] = ()
    children: tuple[RouteGroup, ...] = ()
    child_selection: RouteSelection = RouteSelection.ALL_MATCHES
    bindings: Mapping[str, JsonValue] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if _ROUTE_GROUP_ID.fullmatch(self.id) is None:
            raise ValueError(f"invalid routing group id: {self.id!r}")
        if len(self.responsibility_ids) != len(set(self.responsibility_ids)):
            raise ValueError(f"routing group {self.id!r} repeats a responsibility")
        try:
            encoded = json.dumps(dict(self.bindings), ensure_ascii=False)
        except (TypeError, ValueError) as error:
            raise ValueError(f"routing group {self.id!r} bindings must be JSON-safe") from error
        if len(encoded) > 50_000:
            raise ValueError(f"routing group {self.id!r} bindings exceed 50000 characters")


class RouteTraceEntry(BaseModel):
    model_config = ConfigDict(extra="forbid")

    group_id: str
    path: list[str]
    selected: bool
    score: Annotated[float, Field(ge=0.0, le=1.0)] | None = None


class RoutingDecision(BaseModel):
    """The responsibilities activated for one incoming unit of work."""

    model_config = ConfigDict(extra="forbid")

    active_responsibility_ids: list[str]
    scores: dict[str, Annotated[float, Field(ge=0.0, le=1.0)]] = Field(default_factory=dict)
    bindings: dict[str, dict[str, JsonValue]] = Field(default_factory=dict)
    trace: list[RouteTraceEntry] = Field(default_factory=list)
    routed_at: datetime = Field(default_factory=lambda: datetime.now(UTC))

    @model_validator(mode="after")
    def bounded_bindings(self) -> RoutingDecision:
        encoded = json.dumps(self.bindings, ensure_ascii=False)
        if len(encoded) > 100_000:
            raise ValueError("routing bindings exceed 100000 characters")
        return self


class ResponsibilityRouter(Protocol):
    async def route(
        self,
        work: str,
        candidates: ResponsibilityRegistry,
    ) -> RoutingDecision: ...

    async def route_groups(
        self,
        work: str,
        groups: Mapping[str, ResponsibilityRoute],
    ) -> RoutingDecision: ...

    async def close(self) -> None: ...


class GlobalResponsibilityRouter:
    """Activate global responsibilities without evaluating conditional routes."""

    async def route(
        self,
        work: str,
        candidates: ResponsibilityRegistry,
    ) -> RoutingDecision:
        del work
        return RoutingDecision(active_responsibility_ids=list(candidates.global_ids()))

    async def close(self) -> None:
        return None

    async def route_groups(
        self,
        work: str,
        groups: Mapping[str, ResponsibilityRoute],
    ) -> RoutingDecision:
        del work
        return RoutingDecision(
            active_responsibility_ids=[
                group_id for group_id, route in groups.items() if route.always
            ]
        )


def resolved_responsibility_ids(
    decision: RoutingDecision,
    candidates: ResponsibilityRegistry,
) -> list[str]:
    """Validate a routing decision and return ordered matches plus global responsibilities."""

    candidate_ids = {responsibility.id for responsibility in candidates.responsibilities}
    requested_ids = set(decision.active_responsibility_ids)
    unknown_ids = requested_ids - candidate_ids
    unknown_scores = set(decision.scores) - candidate_ids
    if unknown_ids or unknown_scores:
        unknown = ", ".join(sorted(unknown_ids | unknown_scores))
        raise ResponsibilityRoutingError(
            f"routing decision references unknown responsibilities: {unknown}"
        )
    requested_ids.update(candidates.global_ids())
    return [
        responsibility.id
        for responsibility in candidates.responsibilities
        if responsibility.id in requested_ids
    ]


def _validate_route_groups(
    groups: tuple[RouteGroup, ...],
    candidates: ResponsibilityRegistry,
    *,
    max_depth: int = 8,
) -> set[str]:
    candidate_ids = {item.id for item in candidates.responsibilities}
    group_ids: set[str] = set()
    assigned: set[str] = set()
    visiting: set[int] = set()

    def visit(group: RouteGroup, depth: int) -> None:
        if depth > max_depth:
            raise ResponsibilityRoutingError(
                f"routing hierarchy exceeds maximum depth of {max_depth}"
            )
        identity = id(group)
        if identity in visiting:
            raise ResponsibilityRoutingError(f"routing hierarchy contains a cycle at {group.id}")
        if group.id in group_ids:
            raise ResponsibilityRoutingError(f"duplicate routing group id: {group.id}")
        group_ids.add(group.id)
        visiting.add(identity)
        unknown = set(group.responsibility_ids) - candidate_ids
        if unknown:
            raise ResponsibilityRoutingError(
                f"routing group {group.id!r} references unknown responsibilities: "
                f"{', '.join(sorted(unknown))}"
            )
        duplicate_assignments = set(group.responsibility_ids) & assigned
        if duplicate_assignments:
            raise ResponsibilityRoutingError(
                "responsibilities may belong to only one routing group: "
                + ", ".join(sorted(duplicate_assignments))
            )
        assigned.update(group.responsibility_ids)
        for child in group.children:
            visit(child, depth + 1)
        visiting.remove(identity)

    for root in groups:
        visit(root, 1)
    return assigned


def grouped_responsibility_ids(
    groups: tuple[RouteGroup, ...],
    candidates: ResponsibilityRegistry,
) -> set[str]:
    """Validate a hierarchy and return responsibility IDs owned by its groups."""

    return _validate_route_groups(groups, candidates)


def prune_disabled_route_groups(
    groups: tuple[RouteGroup, ...], disabled_ids: set[str]
) -> tuple[RouteGroup, ...]:
    """Remove explicitly disabled responsibilities and groups with no remaining candidates."""
    result = []
    for group in groups:
        responsibilities = tuple(key for key in group.responsibility_ids if key not in disabled_ids)
        children = prune_disabled_route_groups(group.children, disabled_ids)
        if responsibilities or children:
            result.append(replace(group, responsibility_ids=responsibilities, children=children))
    return tuple(result)


async def resolve_hierarchical_routing(
    work: str,
    candidates: ResponsibilityRegistry,
    groups: tuple[RouteGroup, ...],
    router: ResponsibilityRouter,
    *,
    require_match: bool = True,
) -> RoutingDecision:
    """Route root responsibilities and recursively expand every matching route group."""

    if not groups:
        decision = await router.route(work, candidates)
        active = resolved_responsibility_ids(decision, candidates)
        return decision.model_copy(update={"active_responsibility_ids": active})

    assigned = _validate_route_groups(groups, candidates)
    root_ids = tuple(
        responsibility.id
        for responsibility in candidates.responsibilities
        if responsibility.id not in assigned
    )
    active_ids: set[str] = set()
    responsibility_scores: dict[str, float] = {}
    bindings: dict[str, dict[str, JsonValue]] = {}
    trace: list[RouteTraceEntry] = []

    async def route_responsibilities(responsibility_ids: tuple[str, ...]) -> None:
        if not responsibility_ids:
            return
        registry = candidates.routed(responsibility_ids)
        decision = await router.route(work, registry)
        active_ids.update(resolved_responsibility_ids(decision, registry))
        overlap = set(responsibility_scores) & set(decision.scores)
        if overlap:
            raise ResponsibilityRoutingError(
                "responsibilities were routed more than once: " + ", ".join(sorted(overlap))
            )
        responsibility_scores.update(decision.scores)

    async def route_group_level(
        level: tuple[RouteGroup, ...],
        selection: RouteSelection,
        parent_path: tuple[str, ...],
    ) -> None:
        if not level:
            return
        route_groups = getattr(router, "route_groups", None)
        if not callable(route_groups):
            raise ResponsibilityRoutingError(
                "configured router does not support hierarchical route groups"
            )
        routes = {group.id: group.route for group in level}
        decision = await route_groups(work, routes)
        known = set(routes)
        unknown = (set(decision.active_responsibility_ids) | set(decision.scores)) - known
        if unknown:
            raise ResponsibilityRoutingError(
                "routing decision references unknown groups: " + ", ".join(sorted(unknown))
            )
        selected = set(decision.active_responsibility_ids)
        selected.update(group.id for group in level if group.route.always)
        if selection is RouteSelection.BEST_MATCH:
            conditional = [
                group
                for group in level
                if not group.route.always and group.id in selected
            ]
            if conditional:
                winner = max(conditional, key=lambda group: decision.scores.get(group.id, -1.0))
                selected.difference_update(group.id for group in conditional)
                selected.add(winner.id)

        for group in level:
            matched = group.id in selected
            path = (*parent_path, group.id)
            trace.append(
                RouteTraceEntry(
                    group_id=group.id,
                    path=list(path),
                    selected=matched,
                    score=decision.scores.get(group.id),
                )
            )
            if not matched:
                continue
            if group.bindings:
                bindings[group.id] = dict(group.bindings)
            await route_responsibilities(group.responsibility_ids)
            await route_group_level(group.children, group.child_selection, path)

    await route_responsibilities(root_ids)
    await route_group_level(groups, RouteSelection.ALL_MATCHES, ())
    ordered_active = [
        responsibility.id
        for responsibility in candidates.responsibilities
        if responsibility.id in active_ids
    ]
    if not ordered_active and require_match:
        raise ResponsibilityRoutingError("routing activated no responsibilities")
    return RoutingDecision(
        active_responsibility_ids=ordered_active,
        scores=responsibility_scores,
        bindings=bindings,
        trace=trace,
    )


def _routing_key(candidate_id: str, *, prefix: str = "responsibility") -> str:
    return f"{prefix}__{candidate_id}"


def _parse_scores(
    response: Any,
    candidate_ids: list[str],
    *,
    prefix: str = "responsibility",
) -> dict[str, float]:
    keys = [_routing_key(candidate_id, prefix=prefix) for candidate_id in candidate_ids]
    raw_values = parse_jev_values(response, keys)
    values = {
        candidate_id: raw_values[key]
        for candidate_id, key in zip(candidate_ids, keys, strict=True) if key in raw_values
    }

    return _normalize_scores(values, candidate_ids)


def _normalize_scores(values: Mapping[str, Any], candidate_ids: list[str]) -> dict[str, float]:
    missing = set(candidate_ids) - set(values)
    if missing:
        raise ResponsibilityRoutingError(
            f"Decision model routing response omitted: {', '.join(sorted(missing))}"
        )

    scores: dict[str, float] = {}
    for candidate_id in candidate_ids:
        raw = values[candidate_id]
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise ResponsibilityRoutingError(
                f"Decision model routing answer for {candidate_id!r} is not numeric"
            )
        score = float(raw)
        if not isfinite(score):
            raise ResponsibilityRoutingError(
                f"Decision model routing answer for {candidate_id!r} is not finite"
            )
        scores[candidate_id] = min(1.0, max(0.0, score))
    return scores


class DecisionResponsibilityRouter:
    """Route responsibilities and groups through a decision-model adapter."""

    def __init__(
        self, adapter: DecisionModelAdapter, *, timeout_seconds: float = 10.0,
        budget: DecisionRequestBudget | None = None,
        usage_recorder: DecisionUsageRecorder | None = None,
    ) -> None:
        self.adapter = adapter
        self.timeout_seconds = timeout_seconds
        self.budget = budget or adapter.budget
        self.usage_recorder = usage_recorder or DecisionUsageRecorder()

    @property
    def model(self) -> str:
        return self.adapter.model

    @model.setter
    def model(self, value: str) -> None:
        self.adapter.model = value

    async def route(
        self,
        work: str,
        candidates: ResponsibilityRegistry,
    ) -> RoutingDecision:
        routed_ids = [
            responsibility.id
            for responsibility in candidates.responsibilities
            if not candidates.route_for(responsibility.id).always
        ]
        if not routed_ids:
            return RoutingDecision(
                active_responsibility_ids=list(candidates.global_ids()),
            )

        scores = await self._score(
            work,
            {
                responsibility_id: candidates.route_for(responsibility_id)
                for responsibility_id in routed_ids
            },
            prefix="responsibility",
        )

        active = set(candidates.global_ids())
        for responsibility_id, score in scores.items():
            if score >= candidates.route_for(responsibility_id).threshold:
                active.add(responsibility_id)
        active_ids = [
            responsibility.id
            for responsibility in candidates.responsibilities
            if responsibility.id in active
        ]
        return RoutingDecision(active_responsibility_ids=active_ids, scores=scores)

    async def route_groups(
        self,
        work: str,
        groups: Mapping[str, ResponsibilityRoute],
    ) -> RoutingDecision:
        routed = {group_id: route for group_id, route in groups.items() if not route.always}
        scores = await self._score(work, routed, prefix="group")
        active = {group_id for group_id, route in groups.items() if route.always}
        for group_id, score in scores.items():
            if score >= groups[group_id].threshold:
                active.add(group_id)
        return RoutingDecision(
            active_responsibility_ids=[group_id for group_id in groups if group_id in active],
            scores=scores,
        )

    async def _score(
        self,
        work: str,
        routes: Mapping[str, ResponsibilityRoute],
        *,
        prefix: str,
    ) -> dict[str, float]:
        if not routes:
            return {}
        try:
            fitted = self.budget.fit(
                {"work": work},
                {
                    _routing_key(candidate_id, prefix=prefix): route.instructions or ""
                    for candidate_id, route in routes.items()
                },
                compact=False,
            )
            questions = {
                _routing_key(candidate_id, prefix=prefix): route.instructions or ""
                for candidate_id, route in routes.items()
            }
            result = await asyncio.wait_for(
                self.adapter.evaluate(fitted.state, questions),
                timeout=self.timeout_seconds + 0.5,
            )
            self.usage_recorder.record(
                result.response, fitted, purpose="routing", model=self.adapter.model,
                provider=self.adapter.provider,
            )
            values = {
                candidate_id: result.values[key]
                for candidate_id in routes
                if (key := _routing_key(candidate_id, prefix=prefix)) in result.values
            }
            scores = _normalize_scores(values, list(routes))
        except TimeoutError as error:
            raise ResponsibilityRoutingError(
                f"{self.adapter.provider} responsibility routing timed out"
            ) from error
        except ResponsibilityRoutingError:
            raise
        except RequestBudgetError as error:
            raise ResponsibilityRoutingError(str(error)) from error
        except Exception as error:
            raise ResponsibilityRoutingError(
                f"{self.adapter.provider} responsibility routing failed: "
                f"{type(error).__name__}: {error}"
            ) from error

        return scores

    async def close(self) -> None:
        await self.adapter.close()


